class LmdbLegacyMalformedOwnerReclamationRegressionTest {
	@ParameterizedTest
	@EnumSource(Corruption.class)
	void malformedOwnerOrNamespaceCannotAuthorizeReclamation(Corruption corruption,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		CapturedStore store = new CapturedStore(directory);
		SailRepository repository = new SailRepository(store);
		byte[] expectedOwner;
		byte[] expectedNamespace;
		byte[] expectedReverseKey;
		byte[] idKey;
		byte[] namespaceKey;
		byte[] namespaceReverseKey;
		try {
			repository.init();
			ValueStore values = (ValueStore) repository.getValueFactory();
			String iriValue = corruption == Corruption.MISSING_NAMESPACE_REVERSE_DIRECT
					? "urn:m:x"
					: "urn:malformed-owner:x";
			var iri = SimpleValueFactory.getInstance().createIRI(iriValue);
			values.startTransaction(true);
			long id = values.getId(iri, true);
			values.commit();
			values.reconstructReferenceCountsOffline();
			assertTrue(values.hasTrustedReferenceCounts());
			byte[] owner = values.getData(id);
			assertNotNull(owner);
			assertTrue(owner.length <= ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES,
					"the fixture requires a directly verifiable reverse key");
			ByteBuffer encoded = ByteBuffer.wrap(owner);
			assertEquals(ValueStoreRecordCodec.URI_VALUE, encoded.get());
			long namespace = Varint.readUnsignedHeap(encoded);
			byte[] namespaceData = values.getData(namespace);
			assertNotNull(namespaceData);
			assertTrue(encoded.hasRemaining());
			long wrongNamespace = ValueIds.createId(ValueIds.T_BNODE, 1_000_000_000L + ValueIds.getValue(namespace));
			if (corruption == Corruption.WRONG_NAMESPACE_ID) {
				assertEquals(null, values.getData(wrongNamespace), "the malformed dependency ID must be unused");
			}
			byte[] malformedOwner = switch (corruption) {
			case OWNER -> {
				byte[] malformed = owner.clone();
				malformed[encoded.position()] = (byte) 0xff;
				yield malformed;
			}
			case WRONG_NAMESPACE_ID -> ownerWithNamespace(owner, encoded.position(), wrongNamespace, false);
			case NONCANONICAL_NAMESPACE_ID -> ownerWithNamespace(owner, encoded.position(), namespace, true);
			case NAMESPACE, MISSING_NAMESPACE_REVERSE_DIRECT, MISSING_NAMESPACE_REVERSE_HASHED -> owner.clone();
			};
			byte[] malformedNamespace = namespaceData.clone();
			if (corruption == Corruption.NAMESPACE) {
				malformedNamespace[1] = (byte) 0xff;
			}
			boolean ownerChanged = corruption != Corruption.NAMESPACE && !corruption.missingNamespaceReverse();
			assertTrue(malformedOwner.length <= ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES);
			idKey = LmdbCompatibilityFixtures.idKey(id);
			namespaceKey = LmdbCompatibilityFixtures.idKey(namespace);
			boolean hashedNamespace = namespaceData.length > ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES;
			namespaceReverseKey = hashedNamespace
					? ValueStoreRecordCodec.hashKey(ValueStoreRecordCodec.hash(namespaceData))
					: namespaceData;
			if (corruption.missingNamespaceReverse()) {
				assertEquals(corruption == Corruption.MISSING_NAMESPACE_REVERSE_HASHED, hashedNamespace,
						"the fixture must exercise the selected physical reverse-key representation");
			}
			values.startTransaction(true);
			values.writeTransaction((stack, txn) -> {
				var db = stack.mallocInt(1);
				E(mdb_dbi_open(txn, (String) null, 0, db));
				if (ownerChanged) {
					MDBVal oldKey = MDBVal.calloc(stack).mv_data(stack.bytes(owner));
					E(mdb_del(txn, db.get(0), oldKey, null));
					MDBVal badKey = MDBVal.calloc(stack).mv_data(stack.bytes(malformedOwner));
					MDBVal ownerId = MDBVal.calloc(stack).mv_data(stack.bytes(idKey));
					E(mdb_put(txn, db.get(0), badKey, ownerId, 0));
				}
				MDBVal key = MDBVal.calloc(stack)
						.mv_data(stack.bytes(
								ownerChanged ? idKey : namespaceKey));
				MDBVal data = MDBVal.calloc(stack)
						.mv_data(stack.bytes(
								ownerChanged ? malformedOwner : malformedNamespace));
				E(mdb_put(txn, db.get(0), key, data, 0));
				if (corruption.missingNamespaceReverse()) {
					MDBVal reverseKey = MDBVal.calloc(stack).mv_data(stack.bytes(namespaceReverseKey));
					MDBVal reverseOwner = MDBVal.calloc(stack);
					assertEquals(MDB_SUCCESS, mdb_get(txn, db.get(0), reverseKey, reverseOwner),
							"the physical namespace reverse key must exist before corruption");
					byte[] actualOwner = new byte[reverseOwner.mv_data().remaining()];
					reverseOwner.mv_data().get(actualOwner);
					assertArrayEquals(namespaceKey, actualOwner, "the reverse key must belong to this namespace");
					assertEquals(MDB_SUCCESS, mdb_del(txn, db.get(0), reverseKey, null),
							"the physical namespace reverse key must be removed");
				}
				if (corruption == Corruption.WRONG_NAMESPACE_ID) {
					byte[] wrongKey = LmdbCompatibilityFixtures.idKey(wrongNamespace);
					E(mdb_put(txn, db.get(0), MDBVal.calloc(stack).mv_data(stack.bytes(wrongKey)),
							MDBVal.calloc(stack).mv_data(stack.bytes(namespaceData)), 0));
					var counts = stack.mallocInt(1);
					E(mdb_dbi_open(txn, "ref_counts", 0, counts));
					E(mdb_put(txn, counts.get(0), MDBVal.calloc(stack).mv_data(stack.bytes(wrongKey)),
							MDBVal.calloc(stack).mv_data(stack.bytes((byte) 1)), 0));
				}
				return null;
			});
			values.commit();
			assertTrue(values.hasTrustedReferenceCounts(), "the corrupt bytes retain an otherwise valid count proof");
			expectedOwner = malformedOwner;
			expectedNamespace = malformedNamespace;
			expectedReverseKey = ownerChanged ? malformedOwner : owner;
			AtomicBoolean checked = new AtomicBoolean();
			values.startTransaction(true);
			try {
				assertTrue(values.gcIdsIfReaderAvailable(Set.of(id), new HashSet<>(), candidates -> {
					store.triples.filterUsedIds(candidates);
					assertTrue(candidates.contains(id), "the real liveness scan must present this owner to GC");
					checked.set(true);
					return true;
				}));
				values.commit();
			} catch (IOException refused) {
				values.rollback();
				assertTrue(refused.getMessage().contains("Malformed") || refused.getMessage().contains("malformed"),
						"a rejected corrupt owner must identify the malformed data");
			}
			assertTrue(checked.get());
		} finally {
			repository.shutDown();
		}
		assertArrayEquals(expectedOwner, LmdbCompatibilityFixtures.nativeGet(directory, null, idKey));
		assertArrayEquals(expectedNamespace, LmdbCompatibilityFixtures.nativeGet(directory, null, namespaceKey));
		assertArrayEquals(idKey, LmdbCompatibilityFixtures.nativeGet(directory, null, expectedReverseKey),
				"a malformed URI dependency must never authorize reclamation");
		if (corruption.missingNamespaceReverse()) {
			assertEquals(null, LmdbCompatibilityFixtures.nativeGet(directory, null, namespaceReverseKey),
					"a missing reverse owner must remain unavailable after refused collection");
		}
		if (corruption == Corruption.WRONG_NAMESPACE_ID) {
			byte[] wrongKey = LmdbCompatibilityFixtures.idKey(
					Varint.readUnsignedHeap(ByteBuffer.wrap(expectedOwner, 1, expectedOwner.length - 1)));
			assertArrayEquals(expectedNamespace, LmdbCompatibilityFixtures.nativeGet(directory, null, wrongKey));
			assertArrayEquals(new byte[] { 1 }, LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts", wrongKey));
		}
	}

	private static byte[] ownerWithNamespace(byte[] owner, int localStart, long namespaceId, boolean noncanonical) {
		ByteBuffer result = ByteBuffer.allocate(10 + owner.length - localStart);
		result.put(owner[0]);
		if (noncanonical) {
			assertTrue(Varint.calcLengthUnsigned(namespaceId) < 9);
			result.put((byte) 0xff).putLong(namespaceId);
		} else {
			Varint.writeUnsigned(result, namespaceId);
		}
		result.put(owner, localStart, owner.length - localStart);
		return java.util.Arrays.copyOf(result.array(), result.position());
	}

	private enum Corruption {
		OWNER,
		NAMESPACE,
		WRONG_NAMESPACE_ID,
		NONCANONICAL_NAMESPACE_ID,
		MISSING_NAMESPACE_REVERSE_DIRECT,
		MISSING_NAMESPACE_REVERSE_HASHED;

		boolean missingNamespaceReverse() {
			return this == MISSING_NAMESPACE_REVERSE_DIRECT || this == MISSING_NAMESPACE_REVERSE_HASHED;
		}
	}

	private static final class CapturedStore extends LmdbStore {
		private TripleStore triples;

		private CapturedStore(Path directory) {
			super(directory.toFile(), new LmdbStoreConfig().setLegacyReferenceCountRepairEnabled(true));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(path, stored, selected, values) -> {
						triples = new TripleStore(path, stored, selected, values);
						return triples;
					}) {
				@Override
				void startBackgroundMaintenanceAfterInitialization() {
					// This test controls the dictionary writer and explicit count reconstruction.
				}
			};
		}
	}
}
